<?php /** 赛事业务视图；负责人：王乐之（2411302）；AI辅助开发。 */ use yii\helpers\Html;$this->title='我的收藏';?><h1>我的收藏</h1><h2>球队</h2><?php if(!$teams):?><p class="empty">暂未收藏球队。</p><?php endif ?><div class="grid"><?php foreach($teams as $x):?><div class="card"><?= Html::a(Html::encode($x->team->name),['team/view','id'=>$x->team_id]) ?></div><?php endforeach ?></div><h2>比赛</h2><?php if(!$matches):?><p class="empty">暂未收藏比赛。</p><?php endif ?><div class="grid"><?php foreach($matches as $x):?><div class="card"><?= Html::a(Html::encode($x->match->homeTeam->name.' vs '.$x->match->awayTeam->name),['match/view','id'=>$x->match_id]) ?></div><?php endforeach ?></div>